            "var cv=document.getElementById('lc');var has3d=(typeof THREE!=='undefined');"
            "if(!has3d){cv.style.display='none';document.getElementById('ncdn').style.display='block';}"
            "var rn=null,sc=null,ca=null,mesh=null,core=null;"
