            "if(s===stage){L[i].className='on';mk.textContent='◌';seen=false;}"
            "else if(order.indexOf(s)<order.indexOf(stage)||stage==='done'){L[i].className='done';mk.textContent='✓';}"
            "else{L[i].className='';mk.textContent='·';}}}"
            "var fails=0,cancelled=false;"
